// Generado desde apps/web/public/vicino-logo-transparent.png (PIL, LANCZOS).
// Embebido en base64 para que el empaquetado de Vercel lo incluya siempre;
// un readFile con ruta calculada no entra en el rastreo de archivos.
// Tamanos de Apple: icon 29/58/87 pt, logo hasta 160x50 pt (aqui 50/100).
export const ASSETS_PASE_APPLE: Readonly<Record<string, string>> = {
  "icon.png":
    "",
  "icon@2x.png":
    "",
  "icon@3x.png":
    "",
  "logo.png":
    "",
  "logo@2x.png":
    "",
};

export function buffersDelPase(): Record<string, Buffer> {
  return Object.fromEntries(Object.entries(ASSETS_PASE_APPLE).map(([nombre, b64]) => [nombre, Buffer.from(b64, "base64")]));
}
